import unittest
from candidate import parse_nested_parens

class TestParseNestedParens(unittest.TestCase):
    def test_parse_nested_parens_normal_case(self):
        self.assertEqual(parse_nested_parens('(()()) ((())) () ((())()())'), [2, 3, 1, 3])

    def test_parse_nested_parens_single_group(self):
        self.assertEqual(parse_nested_parens('(()())'), [2])

    def test_parse_nested_parens_multiple_groups(self):
        self.assertEqual(parse_nested_parens('(()()) ((())) () ((())()()) ()'), [2, 3, 1, 3, 1])

    def test_parse_nested_parens_empty_string(self):
        self.assertEqual(parse_nested_parens(''), [])

    def test_parse_nested_parens_single_empty_group(self):
        self.assertEqual(parse_nested_parens('()'), [1])

    def test_parse_nested_parens_multiple_empty_groups(self):
        self.assertEqual(parse_nested_parens('() () ()'), [1, 1, 1])

    def test_parse_nested_parens_nested_empty_groups(self):
        self.assertEqual(parse_nested_parens('((())) () ((())()()) ()'), [3, 1, 3, 1])

    def test_parse_nested_parens_none_input(self):
        with self.assertRaises(TypeError):
            parse_nested_parens(None)

    def test_parse_nested_parens_non_string_input(self):
        with self.assertRaises(TypeError):
            parse_nested_parens(123)

if __name__ == '__main__':
    unittest.main()
